<section class="single-herbs-guide__section" aria-labelledby="topic-fifteen-foundations"><h4 id="topic-fifteen-foundations"><?php echo s($coughtext('Cough- and wheeze-relieving herbs: general introduction','Hierbas que alivian tos y sibilancia: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($coughtext('Do not begin with the cough alone. Decide whether Lung Qi must rise or descend, whether Phlegm is Hot or Cold, and whether throat, Stomach, bowel or edema supplies the decisive clue.','No empieces solo por la tos. Decide si Qi de Pulmón debe subir o bajar, si la Flema es caliente o fría y si garganta, Estómago, intestino o edema aporta la pista decisiva.')); ?></p><div class="single-herbs-guide__decision"><div><strong><?php echo s($coughtext('Open upward','Abrir arriba')); ?></strong><span>Jie Geng</span></div><div><strong><?php echo s($coughtext('Descend + bowel','Descender + intestino')); ?></strong><span>Xing Ren / Zi Su Zi</span></div><div><strong><?php echo s($coughtext('Lung Heat + edema','Calor Pulmón + edema')); ?></strong><span>Sang Bai Pi</span></div><div><strong><?php echo s($coughtext('Lung + Stomach Heat','Calor Pulmón + Estómago')); ?></strong><span>Pi Pa Ye</span></div></div><aside class="single-herbs-guide__memory-path"><p class="single-herbs-guide__memory-line"><?php echo s($coughtext('Enter the Lung elevator house.','Entra a la casa del elevador del Pulmón.')); ?></p><p><?php echo s($coughtext('Jie Geng opens the chimney upward; Xing Ren rolls down and oils the exit; Sang Bai Pi cools the red Lung and drains the basement; Pi Pa Ye links Lung to Stomach; Kuan Dong Hua muffles the cough; Zi Wan empties the Phlegm bucket; Bai Bu cares for the chronic cough; Zi Su Zi presses the wheezing elevator down.','Jie Geng abre la chimenea arriba; Xing Ren rueda abajo y lubrica la salida; Sang Bai Pi enfría Pulmón rojo y drena sótano; Pi Pa Ye conecta Pulmón-Estómago; Kuan Dong Hua silencia tos; Zi Wan vacía el cubo de Flema; Bai Bu cuida tos crónica; Zi Su Zi presiona abajo el elevador de sibilancia.')); ?></p><p><strong><?php echo s($coughtext('Direction → temperature → companion clue → chronicity.','Dirección → temperatura → pista acompañante → cronicidad.')); ?></strong></p></aside><p class="single-herbs-guide__scope-note"><strong><?php echo s($coughtext('Normalized current list:','Listado vigente normalizado:')); ?></strong> <?php echo s($coughtext('all eight unique herbs appear in the current guideline 2026. Duplicate Zi Wan was removed; Su Zi is shown once under the official name Zi Su Zi.','las ocho hierbas únicas aparecen en el guideline vigente 2026. Se eliminó Zi Wan duplicada; Su Zi aparece una sola vez bajo el nombre oficial Zi Su Zi.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach($coughherbs as $herb): ?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($herb['name']); ?></strong><em><?php echo s($herb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($coughtext('Module + current guideline 2026','Módulo + guideline vigente 2026')); ?></span></div><p><?php echo s($herb['identity']); ?></p></li><?php endforeach; ?></ol></section>
<section class="single-herbs-guide__section" aria-labelledby="topic-fifteen-chapter-map"><h4 id="topic-fifteen-chapter-map"><?php echo s($coughtext('Chapter 6 final selection map', 'Mapa final de selección del capítulo 6')); ?></h4><div class="single-herbs-guide__pattern"><article><strong><?php echo s($coughtext('External versus chronic', 'Externa frente a crónica')); ?></strong><span><?php echo s($coughtext('External cough: Xing Ren or Kuan Dong Hua. Chronic internal-injury cough: Bai Bu or Zi Wan.', 'Tos externa: Xing Ren o Kuan Dong Hua. Tos crónica por lesión interna: Bai Bu o Zi Wan.')); ?></span></article><article><strong><?php echo s($coughtext('Temperature and companion clue', 'Temperatura y pista acompañante')); ?></strong><span><?php echo s($coughtext('Cold: Zi Wan or Zi Su Zi. Heat: Sang Bai Pi. Dryness: Pi Pa Ye. Wheezing: Xing Ren. Hoarseness: Mu Hu Die. Edema: Sang Bai Pi. Chest oppression: Zi Su Zi.', 'Frío: Zi Wan o Zi Su Zi. Calor: Sang Bai Pi. Sequedad: Pi Pa Ye. Sibilancia: Xing Ren. Ronquera: Mu Hu Die. Edema: Sang Bai Pi. Opresión torácica: Zi Su Zi.')); ?></span></article><article><strong><?php echo s($coughtext('Phlegm location', 'Localización de Flema')); ?></strong><span><?php echo s($coughtext('Lung: Chuan Bei Mu, Xing Ren, Zi Wan, Kuan Dong Hua. Stomach: Ban Xia, Xuan Fu Hua, Pi Pa Ye. Channels: Kun Bu, Hai Zao, Zhe Bei Mu. Veiling the orifices: Tian Nan Xing or Zhi Bai Fu Zi.', 'Pulmón: Chuan Bei Mu, Xing Ren, Zi Wan, Kuan Dong Hua. Estómago: Ban Xia, Xuan Fu Hua, Pi Pa Ye. Canales: Kun Bu, Hai Zao, Zhe Bei Mu. Velando orificios: Tian Nan Xing o Zhi Bai Fu Zi.')); ?></span></article></div><p class="single-herbs-guide__scope-note"><strong><?php echo s($coughtext('Direction:', 'Dirección:')); ?></strong> <?php echo s($coughtext('Jie Geng raises and opens; Xing Ren descends. Kuan Dong Hua directly stops cough; Zi Wan transforms Phlegm more strongly. Ting Li Zi is reserved for excess with copious thick sputum or water accumulation, not deficiency cough.', 'Jie Geng eleva y abre; Xing Ren desciende. Kuan Dong Hua detiene directamente la tos; Zi Wan transforma Flema con más fuerza. Ting Li Zi se reserva para exceso con esputo espeso abundante o acumulación de agua, no tos por deficiencia.')); ?></p></section>
<section class="single-herbs-guide__section" aria-labelledby="topic-fifteen-annex"><h4 id="topic-fifteen-annex"><?php echo s($coughtext('Chapter 6 recognition annex', 'Anexo de reconocimiento del capítulo 6')); ?></h4><div class="single-herbs-guide__annex"><h5 class="single-herbs-guide__catalog-heading"><?php echo s($coughtext('Additional herb in current guideline 2026', 'Hierba adicional del guideline vigente 2026')); ?></h5><ol class="single-herbs-guide__category-herbs"><?php foreach ($coughofficialannex as $categoryherb): ?><li class="single-herbs-guide__category-herb"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($coughtext('Current guideline 2026 · outside this module', 'Guideline vigente 2026 · fuera de este módulo')); ?></span></div><p><?php echo s($categoryherb['note']); ?></p></li><?php endforeach; ?></ol><h5 class="single-herbs-guide__catalog-heading"><?php echo s($coughtext('Source monographs outside current guideline 2026', 'Monografías fuente fuera del guideline vigente 2026')); ?></h5><p class="single-herbs-guide__chapter-annex-names"><?php echo s(implode(' · ', $coughchapterannex)); ?></p></div><h5 class="single-herbs-guide__catalog-heading"><?php echo s($coughtext('Verified current Duì Yào', 'Duì Yào vigentes verificados')); ?></h5><div class="single-herbs-guide__comparisons"><?php foreach ($coughduiyao as $pair): ?><?php $url = new moodle_url($ises ? $pair[1] : $pair[0], ['from' => 'single-herbs', 'focus' => (string)$selected['number']]); ?><a class="single-herbs-guide__comparison" href="<?php echo $url->out(false); ?>"><strong><?php echo s($pair[2]); ?></strong><span><?php echo s($coughtext('Open the verified pair card.', 'Abrir la tarjeta verificada de la pareja.')); ?></span></a><?php endforeach; ?></div></section>
<section class="single-herbs-guide__section" aria-labelledby="topic-fifteen-yang"><h4 id="topic-fifteen-yang"><?php echo s($coughtext('Yang comparative fingerprints','Huellas comparativas de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($coughtext('Relative study indices from chapter 8—not doses or clinical percentages.','Índices relativos de estudio del capítulo 8; no son dosis ni porcentajes clínicos.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach($coughcharts as $chart): ?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart['title']); ?></h5><small><?php echo s($chart['figure']); ?></small><?php foreach($chart['items'] as $name=>$value): ?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name); ?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int)$value; ?>%"></span></span><b><?php echo (int)$value; ?></b></div><?php endforeach; ?></article><?php endforeach; ?></div></section>
